const MODEL_STRUCTURE = Object.fromEntries(
  Object.entries(MODEL_STRUCTURE_SOURCE).map(([product, levelRows]) => [
    product,
    levelRows.map(levelRow => {
      const level = Object.keys(LEVELS).find(key => String(LEVELS[key].name || '').trim().toLowerCase() === String(levelRow.levelName || '').trim().toLowerCase());
      if(!level) return null;
      const symptoms = levelRow.symptomNames.map(symptomName => Object.keys(LEVELS[level].symptoms || {}).find(key => String(LEVELS[level].symptoms[key].name || '').trim().toLowerCase() === String(symptomName || '').trim().toLowerCase())).filter(Boolean);
      return { level, symptoms };
    }).filter(Boolean)
  ])
);

// v5.1.6: Restore Toolkit-owned Level 1 entries for every product.
// BIOS, Code, and Troubleshooting Guide remain Toolkit logic/data and are not controlled by Excel model rows.
Object.keys(MODEL_STRUCTURE).forEach(product => {
  ["bios", "error", "manual"].forEach(levelKey => {
    if(!LEVELS[levelKey]) return;
    if(MODEL_STRUCTURE[product].some(item => item.level === levelKey)) return;
    MODEL_STRUCTURE[product].push({
      level: levelKey,
      symptoms: Object.keys(LEVELS[levelKey].symptoms || {})
    });
  });
});
